dataModel:
public enum SkillId { Shooting, Melee, Medicine, Building, Farming, Scavenging }
public sealed record TraitDef(string Id, string Name, string Desc, string[] Opposites, TraitEffect[] Effects, string ArtKey);
public sealed record TraitEffect(string Stat, EffectOp Op, float Value);
public sealed class Survivor {
  public int Id; public string Name = "";
  public Dictionary<SkillId,int> Skills = new();
  public List<string> Traits = new();
  public float Health = 100, Mood = 60;
  public Location Loc; public bool Alive = true;
}
public readonly record struct Location(LocKind Kind, int RefId); // Base, Party, Battle

public sealed class Needs {
  public float Hunger = 100, Thirst = 100; // 0–100
  public float Tired;                     // hours of sleep owed
  public List<Thought> Thoughts = new();
}
public sealed record Thought(string DefId, float Amount, int EndsAtHour);
public sealed record NeedsDef(float FoodPerDay, float WaterPerDay, float EatBelow, float Starving, int TiredAt, int ExhaustedAt, int SleepFrom, int SleepTo);
public interface IFoodSource { int Take(string supplyId, int n); }

public sealed class Survivor { /* … */ public float Health = 100; public bool Infected; public int? UndressedSince; }
public static class Health {
  public const float SevereBelow = 30f;
  public static bool IsSevere(Survivor s) => s.Alive && s.Health < SevereBelow;
  public static void Hurt(World w, Survivor s, float amt, string cause) { /* trait mult, roll, die */ }
}
public sealed record SurvivorDied(int SurvivorId, string Cause, Location Where) : IDomainEvent;

public sealed record ItemDef(string Id, string Name, float Kg, int Value, SlotKind Slot, bool Small, int StackMax, string[] Tags, string ArtKey);
public sealed class ItemInstance { public long Id; public string DefId = ""; public int Count = 1; public List<ItemInstance>? Contents; }
public enum SlotKind { None, Hands, Body, Back }
public sealed class Inventory {
  public Dictionary<SlotKind, ItemInstance?> Worn = new();
  public ItemInstance?[] Pockets = new ItemInstance?[4];
}
public abstract record ItemLocation; // SurvivorSlot, PocketSlot, PackSlot, Armory, Cargo, Container

public enum WeaponKind { Gun, Melee }
public sealed record WeaponDef(string ItemId, WeaponKind Kind, int DmgMin, int DmgMax, int OptRange, float Falloff, int Aim, int Noise, int Cap, string? Calibre, int ReqSkill);
public sealed record CalibreDef(string Id, string Name, float KgPerRound, int BoxSize, string ArtKey);
// on a gun instance
public sealed class GunState { public int Loaded; }

public sealed class Base {
  public int Id; public string Name = ""; public Hex Hex; public BaseTier Tier;
  public Dictionary<string,int> Stock = new();   // supplyId -> units
  public List<ItemInstance> Armory = new();
  public List<BuildingInstance> Buildings = new();
  public DailyLedger Ledger = new();
}
public sealed class DailyLedger { public Dictionary<string, Dictionary<string,int>> Today = new(); } // supply -> reason -> delta

public sealed record BuildingDef(string Id, string Name, Dictionary<string,int> Cost, float Hours, int Max, Dictionary<SkillId,int> Req, BuildingEffect[] Effects, string ArtKey);
public sealed record BuildingEffect(string Kind, float Value); // "beds", "storageKg", "waterPerDay", "healBonus", "farmPlot"
public sealed class BuildingInstance { public long Id; public string DefId = ""; public int BuiltDay; }
public sealed class BuildJob { public long Id; public string DefId = ""; public float HoursDone; }

public sealed record JobDef(string Id, string Name, string Verb, SkillId? Skill, string ArtKey);
public readonly record struct Activity(string JobId, string Reason);
public interface IJobSystem {
  string JobId { get; }
  bool HasWork(Base b, out string whyNot);
  void Work(World w, Base b, IReadOnlyList<Survivor> workers, float hours);
}

public sealed record DailyReport(int Day, int BaseId, Dictionary<string, SupplyFlow> Flows);
public sealed record SupplyFlow(int Start, int End, Dictionary<string,int> In, Dictionary<string,int> Out);
public interface IDailyStep { string Name { get; } void Run(World w, Base b, DayContext ctx); } // ordered list
public sealed record EconomyDef(float RationShare, int RationBelowDays, float HeatWoodPerHead, float ColdBelowC);

public sealed record LootTable(string Id, int RollsMin, int RollsMax, LootEntry[] Entries, string[] Tags);
public sealed record LootEntry(string? ItemId, string? SupplyId, string? TableId, float Weight, int Min = 1, int Max = 1);
public sealed record ContainerDef(string Kind, string Name, string TableId, int SearchAp, string ArtKey);
public sealed class ContainerState { public string Kind = ""; public bool Rolled; public List<ItemInstance> Items = new(); public Dictionary<string,int> Supplies = new(); }
